+const suspendSchema = z.object({
+  userId: z.string().uuid(),
+  suspended: z.boolean(),
+});
+
+/**
+ * Suspend or reinstate a user (admin only). Sets profiles.is_suspended; if the
+ * user is a provider, also flips their provider status (suspended ⇄ approved)
+ * so they leave / re-enter browse. Writes via the service-role client.
+ */
+export async function setUserSuspended(input: {
+  userId: string;
+  suspended: boolean;
+}): Promise<{ ok: boolean }> {
+  await requireRole("admin");
+  const parsed = suspendSchema.safeParse(input);
+  if (!parsed.success) return { ok: false };
+  const { userId, suspended } = parsed.data;
+
+  const admin = createAdminClient();
+  const { data: target } = await admin
+    .from("profiles")
+    .select("role")
+    .eq("id", userId)
+    .maybeSingle();
+  if (!target) return { ok: false };
+
+  const { error } = await admin
+    .from("profiles")
+    .update({ is_suspended: suspended })
+    .eq("id", userId);
+  if (error) return { ok: false };
+
+  if (target.role === "provider") {
+    await admin
+      .from("providers")
+      .update({ status: suspended ? "suspended" : "approved" })
+      .eq("id", userId);
+  }
+
+  revalidatePath("/admin/users");
+  revalidatePath("/admin/reports");
+  return { ok: true };
+}

